/* Builds the deployable Supabase Edge Function bundle for Orbit Rush.
 *
 *   node SUPABASE/build-client.mjs
 *
 * Reads PROTOTYPE/orbit-rush.html + PROTOTYPE/sim.js (single source of
 * truth), inlines sim.js into the page, injects the hosted API base, and
 * writes the generated files into SUPABASE/functions/orbit-rush/.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const outDir = path.join(root, "SUPABASE", "functions", "orbit-rush");
fs.mkdirSync(outDir, { recursive: true });

const sim = fs.readFileSync(path.join(root, "PROTOTYPE", "sim.js"), "utf8");
let html = fs.readFileSync(path.join(root, "PROTOTYPE", "orbit-rush.html"), "utf8");

// Point the client at the edge function's public path and inline sim.js
// (one self-contained page, no second request).
const TAG = '<script src="sim.js"></script>';
if (!html.includes(TAG)) throw new Error("sim.js script tag not found");
if (sim.includes("</script>")) throw new Error("sim.js cannot be inlined (contains </script>)");
html = html.replace(TAG,
  `<script>window.ORBIT_API = "/functions/v1/orbit-rush";</script>\n<script>\n${sim}\n</script>`
);

fs.writeFileSync(path.join(outDir, "client.ts"),
  "// GENERATED by SUPABASE/build-client.mjs — do not edit by hand.\n" +
  "export const HTML = " + JSON.stringify(html) + ";\n");
fs.writeFileSync(path.join(outDir, "sim.js"),
  "// GENERATED copy of PROTOTYPE/sim.js (see build-client.mjs).\n" + sim);
console.log("built", outDir);
